// Помощники редактора симуляции (S-08): поля шага 1 «פרטים כלליים» и шага 2 «לקוח וחשיפה».
// id полей стабильны: simulation-<поле> (info_items.N.text → simulation-info_items-N-text).
import { Page, Locator, expect } from '@playwright/test';
import { Api } from './api';

export const field = (page: Page, name: string): Locator => page.locator(`#simulation-${name.replace(/\./g, '-')}`);

/** Значения шага 1 (все обязательные; длительность и язык — по умолчанию). */
export const GENERAL = {
  role_title: 'נציג/ת מכירות טלפוני/ת QA-AUTO',
  industry: 'אנרגיה סולארית',
  product_or_service: 'מערכת סולארית לגג של בית פרטי',
  target_audience: 'בעלי בתים פרטיים במרכז הארץ',
  call_goal: 'לברר את צורכי הלקוח ולקבוע פגישת ייעוץ בבית הלקוח',
  customer_type: 'warm_lead',
  desired_outcome: 'הלקוח מסכים לפגישת ייעוץ בביתו במועד מוגדר',
};

/** Новый черновик «מאפס»: заполнить шаг 1 (без перехода). */
export async function fillGeneral(page: Page, name: string) {
  await page.goto('/simulations/new?start=scratch');
  await field(page, 'name').fill(name);
  for (const k of ['role_title', 'industry', 'product_or_service', 'target_audience', 'call_goal', 'desired_outcome'] as const) {
    await field(page, k).fill(GENERAL[k]);
  }
  await field(page, 'customer_type').selectOption(GENERAL.customer_type);
}

/** «הבא: …» с ожиданием save_simulation; возвращает ответ RPC. */
export async function nextStep(page: Page, label: string) {
  const resp = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/save_simulation') && r.request().method() === 'POST');
  await page.getByRole('button', { name: `הבא: ${label}` }).click();
  return resp;
}

export const currentStep = (page: Page, step: 'general' | 'customer' | 'objection' | 'offer') =>
  page.locator(`li[data-step="${step}"][aria-current="step"]`);

/** Черновик через UI шага 1 → шаг 2. Возвращает id симуляции. */
export async function createDraftViaStep1(page: Page, name: string) {
  await fillGeneral(page, name);
  const res = await nextStep(page, 'לקוח וחשיפה');
  expect(res.status(), `save_simulation: ${await res.text()}`).toBe(200);
  const body = (await res.json()) as { id: string; status: string; version: number; lineage_id: string };
  await expect(currentStep(page, 'customer')).toBeVisible();
  return body;
}

export type SimRow = {
  id: string; name: string; status: string; version: number; lineage_id: string; language: string;
  duration_minutes: number; end_conditions: string | null; prior_relationship: string | null;
  customer_opening_state: string | null; customer_need: string | null;
  info_items: { text: string; tier: string; reveal_condition: string | null }[] | null;
};

export async function simById(api: Api, id: string): Promise<SimRow> {
  const res = await api.get(
    `simulations?select=id,name,status,version,lineage_id,language,duration_minutes,end_conditions,prior_relationship,customer_opening_state,customer_need,info_items&id=eq.${id}`,
  );
  expect(res.ok(), `simulations: ${res.status()}`).toBeTruthy();
  const rows = (await res.json()) as SimRow[];
  expect(rows, `симуляция ${id} не найдена`).toHaveLength(1);
  return rows[0];
}

/** Ответ генерации черновика сценария подменяется (422) — настоящий AI не вызывается на /draft. */
export async function blockScenarioGeneration(page: Page) {
  await page.route('**/functions/v1/generate-scenario-draft', async (route) => {
    const cors = { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'access-control-allow-methods': 'POST, OPTIONS' };
    if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 200, headers: cors, body: 'ok' });
    return route.fulfill({ status: 422, headers: { ...cors, 'content-type': 'application/json' }, body: JSON.stringify({ error: 'draft_rejected', reasons: [] }) });
  });
}
